import unittest
import textwrap2


class TestWrapWords(unittest.TestCase):
    def test_empty_text(self):
        self.assertEqual(textwrap2.wrap_words("", 5), [])

    def test_all_whitespace_text(self):
        self.assertEqual(textwrap2.wrap_words("   \t\n  ", 5), [])

    def test_single_word_fitting_width(self):
        self.assertEqual(textwrap2.wrap_words("hello", 10), ["hello"])

    def test_single_word_exact_width(self):
        self.assertEqual(textwrap2.wrap_words("hello", 5), ["hello"])

    def test_leading_and_trailing_whitespace_ignored(self):
        self.assertEqual(
            textwrap2.wrap_words("  \t hello \n world  ", 20),
            ["hello world"],
        )

    def test_multiple_whitespace_runs_collapsed_to_single_space(self):
        self.assertEqual(
            textwrap2.wrap_words("one   two\t\tthree\n\nfour", 20),
            ["one two three four"],
        )

    def test_greedy_line_filling_exact_fit(self):
        self.assertEqual(
            textwrap2.wrap_words("ab cd ef", 5),
            ["ab cd", "ef"],
        )

    def test_greedy_line_filling_multiple_lines(self):
        self.assertEqual(
            textwrap2.wrap_words("a bb ccc dddd e", 6),
            ["a bb", "ccc", "dddd e"],
        )

    def test_width_one_with_single_char_words(self):
        self.assertEqual(
            textwrap2.wrap_words("a b c", 1),
            ["a", "b", "c"],
        )

    def test_long_word_split_with_shorter_last_piece(self):
        self.assertEqual(
            textwrap2.wrap_words("abcdefgh", 3),
            ["abc", "def", "gh"],
        )

    def test_long_word_split_exact_multiple_of_width(self):
        self.assertEqual(
            textwrap2.wrap_words("abcdef", 3),
            ["abc", "def"],
        )

    def test_long_word_split_width_one(self):
        self.assertEqual(
            textwrap2.wrap_words("abc", 1),
            ["a", "b", "c"],
        )

    def test_long_word_pieces_placed_like_separate_words_after(self):
        self.assertEqual(
            textwrap2.wrap_words("abcdefg x", 3),
            ["abc", "def", "g x"],
        )

    def test_long_word_pieces_placed_like_separate_words_before_and_after(self):
        self.assertEqual(
            textwrap2.wrap_words("hi abcdefghij ok", 4),
            ["hi", "abcd", "efgh", "ij", "ok"],
        )

    def test_long_word_tail_piece_joins_with_next_word(self):
        self.assertEqual(
            textwrap2.wrap_words("hi abcdefghi z", 4),
            ["hi", "abcd", "efgh", "i z"],
        )

    def test_width_zero_raises_value_error(self):
        with self.assertRaises(ValueError):
            textwrap2.wrap_words("hello", 0)

    def test_width_negative_raises_value_error(self):
        with self.assertRaises(ValueError):
            textwrap2.wrap_words("hello", -1)

    def test_width_less_than_one_on_empty_text_raises_value_error(self):
        with self.assertRaises(ValueError):
            textwrap2.wrap_words("", 0)


if __name__ == "__main__":
    unittest.main()

