import unittest
import calendar2


class TestCalendar2(unittest.TestCase):
    def test_months_with_31_days(self):
        for month in (1, 3, 5, 7, 8, 10, 12):
            with self.subTest(month=month):
                self.assertEqual(calendar2.days_in_month(2023, month), 31)
                self.assertEqual(calendar2.days_in_month(2024, month), 31)

    def test_months_with_30_days(self):
        for month in (4, 6, 9, 11):
            with self.subTest(month=month):
                self.assertEqual(calendar2.days_in_month(2023, month), 30)
                self.assertEqual(calendar2.days_in_month(2024, month), 30)

    def test_february_non_leap_years(self):
        for year in (1, 2, 3, 2021, 2022, 2023):
            with self.subTest(year=year):
                self.assertEqual(calendar2.days_in_month(year, 2), 28)

    def test_february_regular_leap_years(self):
        for year in (4, 8, 2020, 2024):
            with self.subTest(year=year):
                self.assertEqual(calendar2.days_in_month(year, 2), 29)

    def test_february_century_non_leap_years(self):
        for year in (100, 200, 300, 1900, 2100):
            with self.subTest(year=year):
                self.assertEqual(calendar2.days_in_month(year, 2), 28)

    def test_february_quadricentennial_leap_years(self):
        for year in (400, 800, 1600, 2000, 2400):
            with self.subTest(year=year):
                self.assertEqual(calendar2.days_in_month(year, 2), 29)

    def test_boundary_valid_inputs(self):
        self.assertEqual(calendar2.days_in_month(1, 1), 31)
        self.assertEqual(calendar2.days_in_month(1, 12), 31)

    def test_invalid_month_below_range(self):
        for month in (0, -1, -12):
            with self.subTest(month=month):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(2023, month)

    def test_invalid_month_above_range(self):
        for month in (13, 14, 100):
            with self.subTest(month=month):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(2023, month)

    def test_invalid_year_below_one(self):
        for year in (0, -1, -4, -100, -400):
            with self.subTest(year=year):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(year, 1)

    def test_bool_year_rejected(self):
        for year in (True, False):
            with self.subTest(year=year):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(year, 1)

    def test_bool_month_rejected(self):
        for month in (True, False):
            with self.subTest(month=month):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(2023, month)

    def test_non_int_year_rejected(self):
        for year in (2024.0, "2024", None, [2024], (2024,)):
            with self.subTest(year=year):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(year, 1)

    def test_non_int_month_rejected(self):
        for month in (1.0, "1", None, [1], (1,)):
            with self.subTest(month=month):
                with self.assertRaises(ValueError):
                    calendar2.days_in_month(2023, month)


if __name__ == "__main__":
    unittest.main()

